62:         {tabs.map(([k, label]) => (
63:           <a key={k} role="tab" aria-selected={tab === k} href={to(s.org.slug, `projects/${p.id}/${k}`)} onClick={(e) => (e.preventDefault(), navigate(to(s.org.slug, `projects/${p.id}/${k}`)))} className={cx("-mb-px flex shrink-0 items-center gap-1.5 border-b-2 px-2.5 pb-2.5 text-body-medium", tab === k ? "border-accent-500 text-text-primary" : "border-transparent text-text-secondary hover:text-text-primary")}>
