152:       {viewType === "calendar" && <Calendar tasks={tasks} events={s.events.filter((e) => e.project_id === p.id)} projectId={p.id} />}
153:       {viewType === "timeline" && <Timeline tasks={tasks} group={v.group} milestones={p.milestones} projects={[p]} />}
154:     </div>
